// Merge links from all search pages, de-dup within run by job id,
// and skip jobs already recorded in the results sheet (previous runs).
const seen = new Set();

// Seed with job ids already stored in the Result sheet.
try {
  for (const r of $('Get existing jobs').all()) {
    const j = r.json || {};
    const col = String(j.jobid ?? '').replace(/\D/g, '');
    if (col) seen.add(col);
    const link = String(j.link ?? j.applyLink ?? '');
    const m = link.split('?')[0].replace(/\/+$/, '').match(/(\d{5,})$/);
    if (m) seen.add(m[1]);
  }
} catch (e) { /* read node may be empty; ignore */ }

const out = [];
const inputItems = $input.all();
for (let idx = 0; idx < inputItems.length; idx++) {
  const links = inputItems[idx].json.links;
  const arr = Array.isArray(links) ? links : (links ? [links] : []);
  for (const raw of arr) {
    const link = String(raw).split('?')[0].replace(/\/+$/, '').trim();
    if (!link) continue;
    const m = link.match(/(\d{5,})$/);
    const jobid = m ? m[1] : '';
    const key = jobid || link;
    if (seen.has(key)) continue; // already processed this run or a previous run
    seen.add(key);
    out.push({ json: { links: link, jobid }, pairedItem: { item: idx } });
  }
}

return out;

